// Web Audio core: one context, a limiter on the master bus, three buses, and scopes.
//
// A scope belongs to one scene (or page). Everything it starts is tracked and faded out when
// the scope is disposed, so leaving a scene can never leave a loop running.
// Buffers are generated by plain-JS DSP (dsp.js) and cached by key.

export class AudioCore {
  constructor() {
    this.ctx = null;
    this.volume = 0.8;
    this.cache = new Map();
    this.listeners = new Set();
  }

  get ready() {
    return Boolean(this.ctx && this.ctx.state === 'running');
  }

  get sampleRate() {
    return this.ctx ? this.ctx.sampleRate : 44100;
  }

  onState(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  // Must be called from a user gesture the first time (click, key, touch). Pico events are not gestures.
  unlock() {
    if (!this.ctx) {
      const AC = globalThis.AudioContext || globalThis.webkitAudioContext;
      if (!AC) return;
      const ctx = new AC({ latencyHint: 'interactive' });
      this.ctx = ctx;
      const lim = ctx.createDynamicsCompressor();
      lim.threshold.value = -6;
      lim.knee.value = 3;
      lim.ratio.value = 12;
      lim.attack.value = 0.003;
      lim.release.value = 0.2;
      this.master = ctx.createGain();
      this.master.gain.value = this.volume;
      this.master.connect(lim).connect(ctx.destination);
      this.buses = {};
      for (const name of ['room', 'device', 'media']) {
        const g = ctx.createGain();
        g.connect(this.master);
        this.buses[name] = g;
      }
      ctx.onstatechange = () => this.listeners.forEach((fn) => fn(this.ready));
    }
    if (this.ctx.state !== 'running') this.ctx.resume().catch(() => {});
    this.listeners.forEach((fn) => fn(this.ready));
  }

  setVolume(v) {
    this.volume = Math.max(0, Math.min(1, v));
    if (this.master) this.master.gain.setTargetAtTime(this.volume, this.ctx.currentTime, 0.05);
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  // channels: Float32Array[] at sample rate sr.
  toBuffer(channels, sr) {
    const buf = this.ctx.createBuffer(channels.length, channels[0].length, sr);
    channels.forEach((c, i) => buf.copyToChannel(c, i));
    return buf;
  }

  // Cached buffer from a generator: make() → { channels, sr }.
  buffer(key, make) {
    if (!this.ctx) return null;
    if (!this.cache.has(key)) {
      const { channels, sr } = make();
      this.cache.set(key, this.toBuffer(channels, sr));
    }
    return this.cache.get(key);
  }

  scope() {
    return new AudioScope(this);
  }
}

export class AudioScope {
  constructor(core) {
    this.core = core;
    this.voices = new Set();
    this.disposed = false;
  }

  get ctx() {
    return this.core.ctx;
  }

  get ok() {
    return Boolean(this.core.ctx) && !this.disposed;
  }

  // Play a buffer once or looped. Returns a voice: { gain, src, setGain, setRate, stop }.
  play(buffer, { bus = 'device', gain = 1, rate = 1, pan = 0, loop = false, offset = 0, when = 0, fadeIn = 0, duration } = {}) {
    if (!this.ok || !buffer) return null;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = loop;
    src.playbackRate.value = rate;
    const g = ctx.createGain();
    const t = Math.max(ctx.currentTime, when || ctx.currentTime);
    if (fadeIn > 0) {
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(gain, t + fadeIn);
    } else g.gain.value = gain;
    let node = src.connect(g);
    if (pan && ctx.createStereoPanner) {
      const p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      node = node.connect(p);
    }
    node.connect(this.core.buses[bus] || this.core.master);
    if (duration !== undefined) src.start(t, offset, duration);
    else src.start(t, loop ? offset % buffer.duration : offset);
    const voice = {
      src,
      gain: g,
      startedAt: t,
      offset,
      setGain: (v, tc = 0.05) => g.gain.setTargetAtTime(v, ctx.currentTime, tc),
      setRate: (v, tc = 0.03) => src.playbackRate.setTargetAtTime(v, ctx.currentTime, tc),
      stop: (fade = 0.08) => {
        if (voice.stopped) return;
        voice.stopped = true;
        const n = ctx.currentTime;
        try {
          g.gain.cancelScheduledValues(n);
          g.gain.setValueAtTime(g.gain.value, n);
          g.gain.linearRampToValueAtTime(0, n + fade);
          src.stop(n + fade + 0.02);
        } catch {
          /* already stopped */
        }
        this.voices.delete(voice);
      },
    };
    src.onended = () => this.voices.delete(voice);
    this.voices.add(voice);
    return voice;
  }

  loop(buffer, opts = {}) {
    return this.play(buffer, { fadeIn: 0.8, ...opts, loop: true });
  }

  dispose(fade = 0.6) {
    this.disposed = true;
    for (const v of [...this.voices]) v.stop(fade);
    this.voices.clear();
  }
}
